#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXN 200005
#define MAXM 200005

typedef struct {
    int to, next;
} Edge;

Edge edges[MAXM], redges[MAXM];
int head[MAXN], rhead[MAXN];
int ecnt, recnt;
int N, M;

void add_edge(int u, int v) {
    edges[ecnt].to = v;
    edges[ecnt].next = head[u];
    head[u] = ecnt++;

    redges[recnt].to = u;
    redges[recnt].next = rhead[v];
    rhead[v] = recnt++;
}

int comp[MAXN], comp_cnt;
int order[MAXN], vis[MAXN], ord_cnt;

void dfs1(int u) {
    vis[u] = 1;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        if (!vis[v]) dfs1(v);
    }
    order[ord_cnt++] = u;
}

void dfs2(int u, int id) {
    vis[u] = 1;
    comp[u] = id;
    for (int e = rhead[u]; e != -1; e = redges[e].next) {
        int v = redges[e].to;
        if (!vis[v]) dfs2(v, id);
    }
}

void kosaraju() {
    memset(vis, 0, sizeof(vis));
    ord_cnt = 0;
    for (int i = 1; i <= N; i++)
        if (!vis[i]) dfs1(i);
    memset(vis, 0, sizeof(vis));
    comp_cnt = 0;
    for (int i = ord_cnt - 1; i >= 0; i--) {
        int u = order[i];
        if (!vis[u]) dfs2(u, comp_cnt++);
    }
}

int can_reach(int s, int t, int ignore_u, int ignore_v) {
    // BFS from s to t, ignoring edge ignore_u -> ignore_v
    int queue[MAXN], front = 0, back = 0;
    int visited[MAXN] = {0};
    queue[back++] = s;
    visited[s] = 1;
    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (u == ignore_u && v == ignore_v) continue;
            if (!visited[v]) {
                if (v == t) return 1;
                visited[v] = 1;
                queue[back++] = v;
            }
        }
    }
    return 0;
}

int can_reach_rev(int s, int t, int extra_u, int extra_v) {
    // BFS from s to t, with extra edge extra_u -> extra_v added
    int queue[MAXN], front = 0, back = 0;
    int visited[MAXN] = {0};
    queue[back++] = s;
    visited[s] = 1;
    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (!visited[v]) {
                if (v == t) return 1;
                visited[v] = 1;
                queue[back++] = v;
            }
        }
        // treat extra edge
        if (u == extra_u && !visited[extra_v]) {
            if (extra_v == t) return 1;
            visited[extra_v] = 1;
            queue[back++] = extra_v;
        }
    }
    return 0;
}

int main() {
    scanf("%d %d", &N, &M);
    memset(head, -1, sizeof(head));
    memset(rhead, -1, sizeof(rhead));
    ecnt = recnt = 0;
    int u[MAXM], v[MAXM];
    for (int i = 0; i < M; i++) {
        scanf("%d %d", &u[i], &v[i]);
        add_edge(u[i], v[i]);
    }
    kosaraju();

    for (int i = 0; i < M; i++) {
        int a = u[i], b = v[i];
        if (comp[a] == comp[b]) {
            // same component: check if removing edge breaks connectivity from a to b
            if (can_reach(a, b, a, b))
                printf("same\n");
            else
                printf("diff\n");
        } else {
            // different components: check if adding reversed edge merges them
            if (can_reach_rev(b, a, b, a))
                printf("diff\n");
            else
                printf("same\n");
        }
    }
    return 0;
}

