    for(int e=head[u];e;e=nxt[e]){int v=to[e];if(!num[v]){dfs(v);if(low[v]<low[u])low[u]=low[v];}else if(onstack[v]&&num[v]<low[u])low[u]=num[v];}
    if(num[u]==low[u]){scc_count++;int v;do{v=stk[--stktop];onstack[v]=0;comp[v]=scc_count;}while(v!=u);}
}

int countSCC() {
    memset(num,0,sizeof(int)*(N+1)); memset(onstack,0,sizeof(int)*(N+1));
