typedef long long ll;

typedef struct {
    int to, next, id;
} Edge;

typedef struct {
    int u, v;
} Pair;

static int cmp_pair(const void *a, const void *b) {
    const Pair *x = (const Pair *)a;
    const Pair *y = (const Pair *)b;
    if (x->u != y->u) return x->u < y->u ? -1 : 1;
    if (x->v != y->v) return x->v < y->v ? -1 : 1;
    return 0;
}

static int lower_bound_pair(Pair *arr, int n, int u, int v) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (arr[m].u < u || (arr[m].u == u && arr[m].v < v)) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *A = (int *)malloc((M + 1) * sizeof(int));
    int *B = (int *)malloc((M + 1) * sizeof(int));

    Edge *E = (Edge *)malloc((M + 5) * sizeof(Edge));
    Edge *ER = (Edge *)malloc((M + 5) * sizeof(Edge));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    int *headR = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = headR[i] = -1;

    for (int i = 1; i <= M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        A[i] = a;
        B[i] = b;

        E[i].to = b; E[i].id = i; E[i].next = head[a]; head[a] = i;
        ER[i].to = a; ER[i].id = i; ER[i].next = headR[b]; headR[b] = i;
    }

    /* Kosaraju SCC */
    int *vis = (int *)calloc(N + 1, sizeof(int));
    int *order = (int *)malloc((N + 1) * sizeof(int));
    int ordsz = 0;

    int *it = (int *)malloc((N + 1) * sizeof(int));
    int *st = (int *)malloc((N + 1) * sizeof(int));

    for (int s = 1; s <= N; s++) if (!vis[s]) {
        int top = 0;
        st[top++] = s;
        vis[s] = 1;
        it[s] = head[s];
        while (top) {
            int v = st[top - 1];
            int e = it[v];
            while (e != -1 && vis[E[e].to]) e = E[e].next;
            it[v] = e;
            if (e == -1) {
                order[ordsz++] = v;
                top--;
            } else {
                int to = E[e].to;
                it[v] = E[e].next;
                vis[to] = 1;
                it[to] = head[to];
                st[top++] = to;
            }
        }
    }

    int *comp = (int *)calloc(N + 1, sizeof(int));
    int scc_cnt = 0;
    for (int idx = ordsz - 1; idx >= 0; idx--) {
        int s = order[idx];
        if (comp[s]) continue;
        scc_cnt++;
        int top = 0;
        st[top++] = s;
        comp[s] = scc_cnt;
        while (top) {
            int v = st[--top];
            for (int e = headR[v]; e != -1; e = ER[e].next) {
                int to = ER[e].to;
                if (!comp[to]) {
                    comp[to] = scc_cnt;
                    st[top++] = to;
                }
            }
        }
    }

    /* Build SCC DAG and count edges between SCCs */
    int *sz = (int *)calloc(scc_cnt + 1, sizeof(int));
    for (int i = 1; i <= N; i++) sz[comp[i]]++;

    int *indeg = (int *)calloc(scc_cnt + 1, sizeof(int));
    int *outdeg = (int *)calloc(scc_cnt + 1, sizeof(int));

    Pair *pairs = (Pair *)malloc((M + 1) * sizeof(Pair));
    int pcnt = 0;
    for (int i = 1; i <= M; i++) {
        int cu = comp[A[i]], cv = comp[B[i]];
        if (cu != cv) {
            pairs[pcnt].u = cu;
            pairs[pcnt].v = cv;
            pcnt++;
        }
    }
    qsort(pairs, pcnt, sizeof(Pair), cmp_pair);

    Pair *uniq = (Pair *)malloc((pcnt + 1) * sizeof(Pair));
    int *mult = (int *)malloc((pcnt + 1) * sizeof(int));
    int ucnt = 0;
    for (int i = 0; i < pcnt; ) {
        int j = i + 1;
        while (j < pcnt && pairs[j].u == pairs[i].u && pairs[j].v == pairs[i].v) j++;
        uniq[ucnt] = pairs[i];
        mult[ucnt] = j - i;
        outdeg[pairs[i].u]++;
        indeg[pairs[i].v]++;
        ucnt++;
        i = j;
    }

    /* Answer logic:
       - If edge is inside one SCC:
         reversing keeps SCC count same iff SCC size == 1? Actually self-loop reversal unchanged.
         For nontrivial SCC, changing one internal edge can increase SCC count if that edge is "strong bridge".
         Need detect strong bridges inside SCC.
       - For edge between different SCCs:
         condensation DAG remains acyclic before and after.
         Reversing u->v changes SCC count iff it creates a cycle merging SCCs, or breaks count? Reversing an inter-SCC edge cannot split SCCs.
         It changes iff there is a path from u's SCC to v's SCC besides this edge? No, reversing to v->u creates cycle iff there is already path v -> ... -> u in DAG, impossible since edge u->v existed in DAG. So no merge.
         It also deletes u->v; SCC count unchanged. Thus always same.
       So only need strong bridges within SCCs.
    */

    /* Strong bridges in directed graph can be found using dominators on SCC subgraphs:
       edge u->v in SCC is strong bridge iff u dominates v in original flow graph rooted at r
       and v dominates u in reverse graph rooted at r.
       Process each SCC separately.
    */

    char *ans = (char *)malloc((M + 1) * sizeof(char));
    for (int i = 1; i <= M; i++) ans[i] = 0;

    int *verts = (int *)malloc((N + 1) * sizeof(int));
    int *pos = (int *)malloc((N + 1) * sizeof(int));

    int *sccHead = (int *)malloc((scc_cnt + 1) * sizeof(int));
    int *sccNext = (int *)malloc((N + 1) * sizeof(int));
    for (int c = 1; c <= scc_cnt; c++) sccHead[c] = -1;
    for (int v = 1; v <= N; v++) {
        sccNext[v] = sccHead[comp[v]];
        sccHead[comp[v]] = v;
    }

    /* arrays for Lengauer-Tarjan */
    int maxV = N + 5;
    int *arr = (int *)malloc(maxV * sizeof(int));
    int *rev = (int *)malloc(maxV * sizeof(int));
    int *par = (int *)malloc(maxV * sizeof(int));
    int *sdom = (int *)malloc(maxV * sizeof(int));
    int *idom = (int *)malloc(maxV * sizeof(int));
    int *dsu = (int *)malloc(maxV * sizeof(int));
    int *label = (int *)malloc(maxV * sizeof(int));
    int *bucketHead = (int *)malloc(maxV * sizeof(int));
    int *bucketNext = (int *)malloc(maxV * sizeof(int));

    int *predCnt = (int *)malloc(maxV * sizeof(int));
    int *predStart = (int *)malloc(maxV * sizeof(int));
    int *predList = NULL;

    int *domChildHead = (int *)malloc(maxV * sizeof(int));
    int *domChildTo = (int *)malloc(maxV * sizeof(int));
    int *domChildNext = (int *)malloc(maxV * sizeof(int));

    int *tin = (int *)malloc(maxV * sizeof(int));
    int *tout = (int *)malloc(maxV * sizeof(int));

    for (int c = 1; c <= scc_cnt; c++) {
        if (sz[c] == 1) {
            int v = sccHead[c];
            for (int e = head[v]; e != -1; e = E[e].next) {
                if (E[e].to == v) ans[E[e].id] = 0; /* same */
            }
            continue;
        }

        int k = 0;
        for (int v = sccHead[c]; v != -1; v = sccNext[v]) {
            verts[k] = v;
            pos[v] = ++k;
        }
        int root = verts[0];

        /* collect internal edges count */
        int internal_edges = 0;
        for (int i = 1; i <= M; i++) if (comp[A[i]] == c && comp[B[i]] == c) internal_edges++;

        predList = (int *)realloc(predList, (internal_edges + 5) * sizeof(int));

        /* function-like repeated code via macro */
#define BUILD_DOM(REVERSED, IS_REV_GRAPH) do { \
            int T = 0; \
            for (int i = 1; i <= k; i++) { \
                arr[i] = rev[i] = par[i] = sdom[i] = idom[i] = dsu[i] = label[i] = 0; \
                bucketHead[i] = 0; predCnt[i] = 0; \
            } \
            int top = 0; \
            st[top++] = root; \
            int *eit = it; \
            for (int i2 = 0; i2 < top; i2++) {} \
            for (int i2 = 1; i2 <= N; i2++) vis[i2] = 0; \
            vis[root] = 1; \
            int *stackV = st; \
            int *stackE = order; \
            int sp = 0; \
            stackV[sp] = root; \
            if (!(REVERSED)) stackE[sp] = head[root]; else stackE[sp] = headR[root]; \
            arr[++T] = root; rev[root] = T; \
            while (sp >= 0) { \
                int v = stackV[sp]; \
                int *pe = &stackE[sp]; \
                int e = *pe; \
                int advanced = 0; \
                while (e != -1) { \
                    int to = (!(REVERSED)) ? E[e].to : ER[e].to; \
                    int ok = (comp[to] == c); \
                    int ne = (!(REVERSED)) ? E[e].next : ER[e].next; \
                    *pe = ne; \
                    if (!ok) { e = ne; continue; } \
                    if (!vis[to]) { \
                        vis[to] = 1; \
                        par[++T] = rev[v]; \
                        arr[T] = to; rev[to] = T; \
                        sp++; \
                        stackV[sp] = to; \
                        stackE[sp] = (!(REVERSED)) ? head[to] : headR[to]; \
                        advanced = 1; \
                        break; \
                    } \
                    e = ne; \
                } \
                if (!advanced) sp--; \
            } \
            for (int i = 1; i <= T; i++) { sdom[i] = label[i] = dsu[i] = i; predCnt[i] = 0; bucketHead[i] = 0; } \
            for (int i = 1; i <= M; i++) { \
                int x = A[i], y = B[i]; \
                if (comp[x] != c || comp[y] != c) continue; \
                int from = (!(REVERSED)) ? x : y; \
                int to   = (!(REVERSED)) ? y : x; \
                int rf = rev[from], rt = rev[to]; \
                if (rf && rt) predCnt[rt]++; \
            } \
            predStart[1] = 0; \
            for (int i = 2; i <= T + 1; i++) predStart[i] = predStart[i - 1] + predCnt[i - 1]; \
            for (int i = 1; i <= T; i++) predCnt[i] = 0; \
            for (int i = 1; i <= M; i++) { \
