                int rf = rev[from], rt = rev[to]; \
                if (rf && rt) predList[predStart[rt] + predCnt[rt]++] = rf; \
            } \
            int *best = label; \
            int *uf = dsu; \
            int evalstk_sz; \
            int *tmpstk = verts; \
            int find_eval(int x) { \
                evalstk_sz = 0; \
                int y = x; \
                while (uf[y] != y) { tmpstk[evalstk_sz++] = y; y = uf[y]; } \
                while (evalstk_sz) { \
                    int z = tmpstk[--evalstk_sz]; \
                    if (sdom[best[uf[z]]] < sdom[best[z]]) best[z] = best[uf[z]]; \
                    uf[z] = y; \
                } \
                return best[x]; \
            } \
            void unite_fn(int x, int y) { uf[y] = x; } \
            for (int i = T; i >= 2; i--) { \
                for (int pidx = predStart[i]; pidx < predStart[i] + predCnt[i]; pidx++) { \
                    int p = predList[pidx]; \
                    int q = find_eval(p); \
                    if (sdom[q] < sdom[i]) sdom[i] = sdom[q]; \
                } \
                bucketNext[i] = bucketHead[sdom[i]]; \
                bucketHead[sdom[i]] = i; \
                unite_fn(par[i], i); \
                int b = bucketHead[par[i]]; \
                while (b) { \
                    int v = b; \
                    b = bucketNext[b]; \
                    int q = find_eval(v); \
                    idom[v] = (sdom[q] == sdom[v]) ? sdom[v] : q; \
                } \
