                    sp2--; \
                } \
            } \
            for (int i = 1; i <= M; i++) { \
                int x = A[i], y = B[i]; \
                if (comp[x] != c || comp[y] != c) continue; \
                int from = (!(REVERSED)) ? x : y; \
                int to   = (!(REVERSED)) ? y : x; \
                int rf = rev[from], rt = rev[to]; \
                if (rf && rt && par[rt] == rf) { \
                    if (IS_REV_GRAPH) ans[i] |= 2; \
