                } \
            } \
        } while (0)

        BUILD_DOM(0, 0);
        BUILD_DOM(1, 1);
#undef BUILD_DOM
    }

    for (int i = 1; i <= M; i++) {
        if (comp[A[i]] != comp[B[i]]) {
            puts("same");
        } else if (sz[comp[A[i]]] == 1) {
