    }

    free(A); free(B); free(E); free(ER); free(head); free(headR);
    free(vis); free(order); free(it); free(st); free(comp);
    free(sz); free(indeg); free(outdeg); free(pairs); free(uniq); free(mult);
    free(ans); free(verts); free(pos); free(sccHead); free(sccNext);
