#include <bits/stdc++.h>
using namespace std;

int n, m;
vector<pair<int,int>> edges;

int countSCC(vector<pair<int,int>>& edgeList) {
    vector<vector<int>> adj(n+1), radj(n+1);
    for (auto& [a,b] : edgeList) {
        adj[a].push_back(b);
        radj[b].push_back(a);
    }
    // Kosaraju
    vector<bool> visited(n+1, false);
    vector<int> order;
    function<void(int)> dfs1 = [&](int u) {
        visited[u] = true;
        for (int v : adj[u]) if (!visited[v]) dfs1(v);
        order.push_back(u);
    };
    for (int i = 1; i <= n; i++) if (!visited[i]) dfs1(i);

    int scc = 0;
    fill(visited.begin(), visited.end(), false);
    function<void(int)> dfs2 = [&](int u) {
        visited[u] = true;
        for (int v : radj[u]) if (!visited[v]) dfs2(v);
    };
    for (int i = n-1; i >= 0; i--) {
        int u = order[i];
        if (!visited[u]) { scc++; dfs2(u); }
    }
    return scc;
}

int main(){
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n >> m;
    edges.resize(m);
    for (int i = 0; i < m; i++) {
        cin >> edges[i].first >> edges[i].second;
    }

    // original SCC count
    int orig = countSCC(edges);

    for (int i = 0; i < m; i++) {
        vector<pair<int,int>> modified;
        for (int j = 0; j < m; j++) {
            if (j == i) modified.push_back({edges[i].second, edges[i].first});
            else modified.push_back(edges[j]);
        }
        int newCount = countSCC(modified);
        if (newCount == orig) cout << "same\n";
        else cout << "diff\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct SCC {
    int n;
    vector<vector<int>> g, rg;
    vector<int> comp, order;
    vector<bool> used;

    SCC(int n) : n(n), g(n), rg(n), comp(n, -1), used(n, false) {}

    void add_edge(int from, int to) {
        g[from].push_back(to);
        rg[to].push_back(from);
    }

    void dfs(int v) {
        used[v] = true;
