struct SCC {
    int n;
    vector<vector<int>> g, rg;
    vector<int> comp, order, vis;
    int cnt = 0;

    SCC(int n = 0) : n(n), g(n), rg(n) {}

    void add_edge(int u, int v) {
        g[u].push_back(v);
        rg[v].push_back(u);
    }

    void dfs1(int v) {
        vis[v] = 1;
        for (int to : g[v]) if (!vis[to]) dfs1(to);
        order.push_back(v);
    }

    void dfs2(int v, int c) {
        comp[v] = c;
        for (int to : rg[v]) if (comp[to] == -1) dfs2(to, c);
    }

    int build() {
        vis.assign(n, 0);
        order.clear();
        for (int i = 0; i < n; i++) if (!vis[i]) dfs1(i);
        comp.assign(n, -1);
        cnt = 0;
        for (int i = n - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) dfs2(v, cnt++);
        }
        return cnt;
    }
};

struct BridgeFinder {
    int n, timer = 0;
    vector<vector<pair<int,int>>> g; // to, edge id
    vector<int> tin, low;
    vector<char> isBridge;

    BridgeFinder(int n = 0) : n(n), g(n) {}

    void add_edge(int u, int v, int id) {
        g[u].push_back({v, id});
        g[v].push_back({u, id});
    }

    void dfs(int v, int peid) {
        tin[v] = low[v] = ++timer;
        for (auto [to, id] : g[v]) {
            if (id == peid) continue;
            if (tin[to]) {
                low[v] = min(low[v], tin[to]);
            } else {
                dfs(to, id);
                low[v] = min(low[v], low[to]);
                if (low[to] > tin[v]) isBridge[id] = 1;
            }
        }
    }

    vector<char> solve(int m) {
        tin.assign(n, 0);
        low.assign(n, 0);
        isBridge.assign(m, 0);
        timer = 0;
        for (int i = 0; i < n; i++) if (!tin[i]) dfs(i, -1);
        return isBridge;
    }
};

