        return id;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        M = Integer.parseInt(st.nextToken());
        g = new ArrayList[N];
        rg = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }
        int[] a = new int[M];
        int[] b = new int[M];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken())-1;
            int v = Integer.parseInt(st.nextToken())-1;
            a[i] = u; b[i] = v;
            g[u].add(v);
            rg[v].add(u);
        }

        int sccCount = kosaraju();

        // Build DAG of SCCs
        int C = sccCount;
        Set<Long> edgeSet = new HashSet<>();
        List<Integer>[] dag = new ArrayList[C];
        List<Integer>[] dagRev = new ArrayList[C];
        for (int i = 0; i < C; i++) {
            dag[i] = new ArrayList<>();
            dagRev[i] = new ArrayList<>();
        }
        for (int u = 0; u < N; u++) {
            for (int v : g[u]) {
                int cu = comp[u], cv = comp[v];
                if (cu != cv) {
                    long key = (long)cu * C + cv;
                    if (!edgeSet.contains(key)) {
                        edgeSet.add(key);
                        dag[cu].add(cv);
                        dagRev[cv].add(cu);
                    }
                }
            }
        }

        // For each SCC node, compute topological order
        int[] orderSCC = new int[C];
        int[] indeg = new int[C];
        for (int u = 0; u < C; u++) {
            for (int v : dag[u]) indeg[v]++;
        }
        Queue<Integer> q = new LinkedList<>();
        for (int i = 0; i < C; i++) if (indeg[i] == 0) q.add(i);
        int idx = 0;
        while (!q.isEmpty()) {
            int u = q.poll();
            orderSCC[idx++] = u;
            for (int v : dag[u]) {
                indeg[v]--;
                if (indeg[v] == 0) q.add(v);
            }
        }

        // For each edge, determine if it's a bridge in DAG
        // We'll compute reachability counts from each node using bitsets if C <= 2000, else use alternative
        boolean[] isBridge = new boolean[M];
        if (C <= 2000) {
            BitSet[] reach = new BitSet[C];
            for (int i = C-1; i >= 0; i--) {
                int u = orderSCC[i];
                reach[u] = new BitSet();
                reach[u].set(u);
                for (int v : dag[u]) {
                    reach[u].or(reach[v]);
                }
            }
            for (int i = 0; i < M; i++) {
                int cu = comp[a[i]], cv = comp[b[i]];
                if (cu == cv) {
                    isBridge[i] = false;
                } else {
                    // check if there is another path from cu to cv
                    boolean anotherPath = false;
                    for (int w : dag[cu]) {
                        if (w != cv && reach[w].get(cv)) {
                            anotherPath = true;
                            break;
                        }
                    }
                    isBridge[i] = !anotherPath;
                }
            }
        } else {
            // Fallback: For each edge, run BFS from cu without using that edge
            for (int i = 0; i < M; i++) {
                int cu = comp[a[i]], cv = comp[b[i]];
                if (cu == cv) {
                    isBridge[i] = false;
                    continue;
                }
                // BFS from cu, not using edge cu->cv
                boolean[] vis = new boolean[C];
                Queue<Integer> queue = new LinkedList<>();
                queue.add(cu);
                vis[cu] = true;
                while (!queue.isEmpty()) {
                    int u = queue.poll();
                    for (int v : dag[u]) {
                        if (!(u == cu && v == cv) && !vis[v]) {
                            vis[v] = true;
                            queue.add(v);
                        }
                    }
                }
                isBridge[i] = !vis[cv];
            }
        }

        PrintWriter out = new PrintWriter(System.out);
        for (int i = 0; i < M; i++) {
            out.println(isBridge[i] ? "diff" : "same");
        }
        out.flush();
    }
}

