import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int from, to;
        Edge(int f, int t) { from = f; to = t; }
    }

    static int N, M;
    static Edge[] edges;
    static ArrayList<Integer>[] g, rg;

    static int[] comp;
    static boolean[] used;
    static int[] order;
    static int orderPtr = 0;

    static void dfs1Iter(int start) {
        ArrayDeque<int[]> st = new ArrayDeque<>();
        st.push(new int[]{start, 0});
        used[start] = true;
        while (!st.isEmpty()) {
            int[] cur = st.peek();
            int v = cur[0], idx = cur[1];
            if (idx < g[v].size()) {
                int to = g[v].get(idx);
                cur[1]++;
                if (!used[to]) {
                    used[to] = true;
                    st.push(new int[]{to, 0});
                }
            } else {
                order[orderPtr++] = v;
                st.pop();
            }
        }
    }

    static void dfs2Iter(int start, int cid) {
        ArrayDeque<Integer> st = new ArrayDeque<>();
        st.push(start);
        comp[start] = cid;
        while (!st.isEmpty()) {
            int v = st.pop();
            for (int to : rg[v]) {
                if (comp[to] == -1) {
                    comp[to] = cid;
                    st.push(to);
                }
            }
        }
    }

    // Bridge finder in undirected multigraph of SCC condensation
    static class BridgeFinder {
        int n;
        ArrayList<int[]>[] adj; // {to, edgeId}
        int[] tin, low;
        boolean[] visited;
        boolean[] isBridge;
        int timer = 0;

        BridgeFinder(int n, int m) {
            this.n = n;
            adj = new ArrayList[n];
            for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
            tin = new int[n];
            low = new int[n];
            visited = new boolean[n];
            isBridge = new boolean[m];
        }

        void addEdge(int u, int v, int id) {
            adj[u].add(new int[]{v, id});
            adj[v].add(new int[]{u, id});
        }

        void findBridges() {
            for (int i = 0; i < n; i++) {
                if (!visited[i]) dfsIter(i);
            }
        }

        void dfsIter(int root) {
            class Frame {
                int v, parent, parentEdge, idx;
                Frame(int v, int parent, int parentEdge, int idx) {
                    this.v = v; this.parent = parent; this.parentEdge = parentEdge; this.idx = idx;
                }
            }

            ArrayDeque<Frame> st = new ArrayDeque<>();
            st.push(new Frame(root, -1, -1, 0));
            visited[root] = true;
            tin[root] = low[root] = timer++;

            while (!st.isEmpty()) {
                Frame f = st.peek();
                int v = f.v;
                if (f.idx < adj[v].size()) {
                    int[] e = adj[v].get(f.idx++);
                    int to = e[0], id = e[1];
                    if (id == f.parentEdge) continue;
                    if (visited[to]) {
                        low[v] = Math.min(low[v], tin[to]);
                    } else {
                        visited[to] = true;
                        tin[to] = low[to] = timer++;
                        st.push(new Frame(to, v, id, 0));
                    }
                } else {
                    st.pop();
                    if (f.parent != -1) {
                        low[f.parent] = Math.min(low[f.parent], low[v]);
                        if (low[v] > tin[f.parent]) {
                            isBridge[f.parentEdge] = true;
                        }
                    }
                }
            }
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        M = fs.nextInt();

        edges = new Edge[M];
        g = new ArrayList[N];
        rg = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < M; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            edges[i] = new Edge(a, b);
            g[a].add(b);
            rg[b].add(a);
        }

        // SCC decomposition
        used = new boolean[N];
        order = new int[N];
        for (int i = 0; i < N; i++) {
            if (!used[i]) dfs1Iter(i);
        }

        comp = new int[N];
        Arrays.fill(comp, -1);
        int sccCnt = 0;
        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) {
                dfs2Iter(v, sccCnt++);
                sccCnt++;
            }
        }
        // Oops, above increments twice; fix by recomputing properly
        Arrays.fill(comp, -1);
        sccCnt = 0;
        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) {
                dfs2Iter(v, sccCnt);
                sccCnt++;
            }
        }

        // Build undirected condensation multigraph with one edge per original cross-SCC edge
        int[] condensedEdgeId = new int[M];
        Arrays.fill(condensedEdgeId, -1);

        int crossCount = 0;
        for (int i = 0; i < M; i++) {
            int cu = comp[edges[i].from];
            int cv = comp[edges[i].to];
            if (cu != cv) crossCount++;
        }

        BridgeFinder bf = new BridgeFinder(sccCnt, crossCount);
        int eid = 0;
        for (int i = 0; i < M; i++) {
            int cu = comp[edges[i].from];
            int cv = comp[edges[i].to];
            if (cu != cv) {
                condensedEdgeId[i] = eid;
                bf.addEdge(cu, cv, eid);
                eid++;
            }
        }
        bf.findBridges();

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < M; i++) {
            int cu = comp[edges[i].from];
            int cv = comp[edges[i].to];
            if (cu == cv) {
                out.append("same\n");
            } else {
                int id = condensedEdgeId[i];
                if (bf.isBridge[id]) out.append("diff\n");
                else out.append("same\n");
            }
        }

        System.out.print(out.toString());
    }
}
